<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class AvailabilityRequest extends FormRequest { public function authorize(): bool{return $this->user()?->role==='vet';} public function rules(): array{return ['day_of_week'=>'required|integer|min:0|max:6','start_time'=>'required|date_format:H:i','end_time'=>'required|date_format:H:i|after:start_time','is_active'=>'boolean'];} }